--          ▀▀▀▀▀▀▀▀▀▀▀  ▀▀▀▀▀▀▀
--
-- `mini.starter` is configured to look like a small dashboard:
--   * an ASCII "NEOVIM" logo, painted with a gradient taken from the current
--     colorscheme (the `paint_header` content hook splits the logo into one
--     character per content unit so that every column can get its own color),
--   * a few handy actions, followed by recently opened files,
--   * a compact footer with version info and usage hints.
--
-- See `:help MiniStarter` and `:help MiniStarter-config` for the full story.

local function gh(repo) return 'https://github.com/' .. repo end

vim.pack.add { gh 'nvim-mini/mini.nvim' }

local starter = require 'mini.starter'

-- Logo ------------------------------------------------------------------------

local logo = {
  '███╗   ██╗███████╗ ██████╗ ██╗   ██╗██╗███╗   ███╗',
  '████╗  ██║██╔════╝██╔═══██╗██║   ██║██║████╗ ████║',
  '██╔██╗ ██║█████╗  ██║   ██║██║   ██║██║██╔████╔██║',
  '██║╚██╗██║██╔══╝  ██║   ██║╚██╗ ██╔╝██║██║╚██╔╝██║',
  '██║ ╚████║███████╗╚██████╔╝ ╚████╔╝ ██║██║ ╚═╝ ██║',
  '╚═╝  ╚═══╝╚══════╝ ╚═════╝   ╚═══╝  ╚═╝╚═╝     ╚═╝',
}

local signature = '✦  F I R M I A N A  ✦'

-- Split every logo line into one content unit per character. Each unit points
-- to its own highlight group (`StarterLogoN`), which is what creates the
-- horizontal gradient.
local logo_units, logo_width = {}, 0
for line_num, line in ipairs(logo) do
  local chars = vim.fn.split(line, '\\zs')
  logo_width = math.max(logo_width, #chars)

  logo_units[line_num] = {}
  for col, char in ipairs(chars) do
    logo_units[line_num][col] = { string = char, type = 'header', hl = 'StarterLogo' .. col }
  end
end

-- Colors ----------------------------------------------------------------------

-- Foreground of a highlight group, falling back to a fixed color when the
-- active colorscheme does not define it.
local function hl_fg(name, fallback)
  local ok, hl = pcall(vim.api.nvim_get_hl, 0, { name = name, link = false })
  if ok and type(hl) == 'table' and hl.fg then return ('#%06x'):format(hl.fg) end
  return fallback
end

local function hex_to_rgb(hex) return tonumber(hex:sub(2, 3), 16), tonumber(hex:sub(4, 5), 16), tonumber(hex:sub(6, 7), 16) end

local function mix(color_a, color_b, t)
  local r1, g1, b1 = hex_to_rgb(color_a)
  local r2, g2, b2 = hex_to_rgb(color_b)
  local mix_channel = function(a, b) return math.floor(a + (b - a) * t + 0.5) end
  return ('#%02x%02x%02x'):format(mix_channel(r1, r2), mix_channel(g1, g2), mix_channel(b1, b2))
end

-- `n` colors sampled from a gradient which goes through `stops` (at least two).
local function gradient(stops, n)
  local colors, n_segments = {}, #stops - 1
  for i = 1, n do
    local position = n == 1 and 0 or ((i - 1) / (n - 1)) * n_segments
    local segment = math.min(math.floor(position) + 1, n_segments)
    colors[i] = mix(stops[segment], stops[segment + 1], position - (segment - 1))
  end
  return colors
end

local define_highlights = function()
  -- Accents are read from the active colorscheme: with tokyonight this gives
  -- cyan -> blue -> purple, and it keeps working for any other theme.
  local cyan = hl_fg('Keyword', '#7dcfff')
  local blue = hl_fg('Function', '#7aa2f7')
  local purple = hl_fg('Identifier', '#bb9af7')
  local dim = hl_fg('Comment', '#565f89')

  for col, color in ipairs(gradient({ cyan, blue, purple }, logo_width)) do
    vim.api.nvim_set_hl(0, 'StarterLogo' .. col, { fg = color })
  end

  vim.api.nvim_set_hl(0, 'StarterSignature', { fg = dim })
  vim.api.nvim_set_hl(0, 'MiniStarterSection', { fg = dim, bold = true })
  vim.api.nvim_set_hl(0, 'MiniStarterItemBullet', { fg = blue })
  vim.api.nvim_set_hl(0, 'MiniStarterItemPrefix', { fg = purple })
  vim.api.nvim_set_hl(0, 'MiniStarterCurrent', { bold = true })
  vim.api.nvim_set_hl(0, 'MiniStarterQuery', { fg = hl_fg('Constant', '#ff9e64'), bold = true })
  vim.api.nvim_set_hl(0, 'MiniStarterFooter', { fg = dim })
end

-- Content hook which replaces the flat header lines with the per character
-- units prepared above.
local function paint_header(content)
  for line_num, units in ipairs(logo_units) do
    content[line_num] = vim.deepcopy(units)
  end

  -- Signature is the line right after the empty line which follows the logo.
  local signature_line = content[#logo + 2]
  if signature_line and signature_line[1] then signature_line[1].hl = 'StarterSignature' end

  return content
end

-- Items -----------------------------------------------------------------------

local telescope = function(picker)
  return function() require('telescope.builtin')[picker]() end
end

-- Item name is what gets filtered by the query, so it has to start with a
-- letter: no icons before the label. Key hints are padded into a column.
local function action(name, keys, cmd, section) return { name = keys and ('%-22s%s'):format(name, keys) or name, action = cmd, section = section } end

local items = {
  action('Find file', '<leader>sf', telescope 'find_files', 'Start'),
  action('Recent files', '<leader>s.', telescope 'oldfiles', 'Start'),
  action('Live grep', '<leader>sg', telescope 'live_grep', 'Start'),
  action('Buffers', '<leader><leader>', telescope 'buffers', 'Start'),
  action('Configuration', '<leader>sn', function() require('telescope.builtin').find_files { cwd = vim.fn.stdpath 'config', follow = true } end, 'Start'),
  action('File explorer', '\\', function() vim.cmd 'Neotree focus' end, 'Start'),
  action('New file', nil, function() vim.cmd 'enew' end, 'Start'),
  starter.sections.recent_files(6, false, false),
}

-- Footer ----------------------------------------------------------------------

-- Count installed plugins once, lazily (used only in the footer).
local plugin_count = (function()
  local count
  return function()
    if count then return count end
    local dir = vim.fs.joinpath(vim.fn.stdpath 'data', 'site', 'pack', 'core', 'opt')
    local ok, entries = pcall(vim.fn.readdir, dir)
    count = (ok and type(entries) == 'table') and #entries or 0
    return count
  end
end)()

local footer = function()
  local version = vim.version()
  return ('%s  ·  %d plugins  ·  firmiana'):format(('nvim %d.%d.%d'):format(version.major, version.minor, version.patch), plugin_count())
    .. '\n'
    .. 'type to filter  ·  <CR> open  ·  <C-c> close'
end

-- Setup -----------------------------------------------------------------------

-- Header is the logo, an empty line and the signature centered underneath.
local signature_indent = math.max(math.floor((logo_width - vim.fn.strdisplaywidth(signature)) / 2), 0)
local header_lines = vim.list_extend({}, logo)
vim.list_extend(header_lines, { '', string.rep(' ', signature_indent) .. signature })

starter.setup {
  header = table.concat(header_lines, '\n'),
  footer = footer,
  items = items,
  content_hooks = {
    paint_header,
    starter.gen_hook.adding_bullet '▸ ',
    starter.gen_hook.aligning('center', 'center'),
  },
}

define_highlights()

local augroup = vim.api.nvim_create_augroup('FirmianaStarter', {})

-- `:hi clear` (done by most colorschemes) forgets the groups defined above.
-- `mini.starter` recreates its own defaults on `ColorScheme`, so register this
-- afterwards to win the race and keep the logo gradient in sync with the theme.
vim.api.nvim_create_autocmd('ColorScheme', {
  group = augroup,
  callback = define_highlights,
  desc = 'Recolor the start screen',
})

-- `mini.starter` re-aligns on `VimResized` and `BufEnter` only, so when a
-- sidebar takes width away from the start screen window (neo-tree), the page
-- keeps its old padding and looks off-center. Re-layout in the same event-loop
-- tick, so the corrected padding is in place before the redraw (waiting even a
-- few milliseconds makes the page visibly jump), and skip the work when the
-- page is already centered.
local reflow_scheduled = false

local function leading_pad(line) return #((line or ''):match '^( *)') end

-- Pad the start screen currently has in `buf`.
local function current_pad(buf) return leading_pad((vim.api.nvim_buf_get_lines(buf, 0, 1, false))[1]) end

-- Pad the `aligning` hook would use for `buf` displayed in `win`.
local function centered_pad(buf, win)
  local content = starter.get_content(buf)
  if not content then return current_pad(buf) end

  local lines = starter.content_to_lines(content)
  local pad = leading_pad(lines[1])
  local width = 0
  for _, line in ipairs(lines) do
    width = math.max(width, vim.fn.strdisplaywidth(line))
  end
  return math.max(math.floor((vim.api.nvim_win_get_width(win) - (width - pad)) / 2), 0)
end

local function reflow()
  if reflow_scheduled then return end
  reflow_scheduled = true
  vim.schedule(function()
    reflow_scheduled = false
    for _, win in ipairs(vim.api.nvim_list_wins()) do
      local buf = vim.api.nvim_win_get_buf(win)
      if vim.bo[buf].filetype == 'ministarter' and current_pad(buf) ~= centered_pad(buf, win) then
        -- `refresh()` only *adds* highlight extmarks, so drop the old ones to
        -- keep them from piling up on every layout change.
        vim.api.nvim_buf_clear_namespace(buf, -1, 0, -1)
        starter.refresh(buf)
      end
    end
  end)
end

vim.api.nvim_create_autocmd({ 'WinNew', 'WinClosed', 'WinResized', 'VimResized', 'BufEnter' }, {
  group = augroup,
  callback = reflow,
  desc = 'Re-center the start screen after layout changes',
})

